import hashlib
import uuid
from datetime import datetime, timezone

import bcrypt

_users: dict[str, dict] = {}


def _hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")


def _verify_password(password: str, hashed: str) -> bool:
    return bcrypt.checkpw(password.encode("utf-8"), hashed.encode("utf-8"))


class User:
    def __init__(
        self,
        id: str,
        email: str,
        password_hash: str,
        name: str,
        role: str = "user",
        created_at: str | None = None,
        updated_at: str | None = None,
    ):
        self.id = id
        self.email = email
        self.password_hash = password_hash
        self.name = name
        self.role = role
        self.created_at = created_at or datetime.now(timezone.utc).isoformat()
        self.updated_at = updated_at or self.created_at

    def to_dict(self, include_sensitive: bool = False) -> dict:
        data = {
            "id": self.id,
            "email": self.email,
            "name": self.name,
            "role": self.role,
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }
        if include_sensitive:
            data["password_hash"] = self.password_hash
        return data

    @classmethod
    def create(cls, email: str, password: str, name: str, role: str = "user") -> "User":
        email = email.lower().strip()
        if email in _users:
            raise ValueError("Email already exists")
        user_id = str(uuid.uuid4())
        user = cls(
            id=user_id,
            email=email,
            password_hash=_hash_password(password),
            name=name,
            role=role,
        )
        _users[email] = user.to_dict(include_sensitive=True)
        return user

    @classmethod
    def find_by_email(cls, email: str) -> "User | None":
        data = _users.get(email.lower().strip())
        if not data:
            return None
        return cls(**data)

    @classmethod
    def find_by_id(cls, user_id: str) -> "User | None":
        for data in _users.values():
            if data["id"] == user_id:
                return cls(**data)
        return None

    @classmethod
    def list_all(cls, page: int = 1, per_page: int = 20) -> tuple[list["User"], int]:
        all_users = [cls(**data) for data in _users.values()]
        total = len(all_users)
        start = (page - 1) * per_page
        end = start + per_page
        return all_users[start:end], total

    @classmethod
    def update(cls, user_id: str, **kwargs) -> "User | None":
        user = cls.find_by_id(user_id)
        if not user:
            return None
        for key in ("name", "role"):
            if key in kwargs:
                _users[user.email][key] = kwargs[key]
        if "email" in kwargs and kwargs["email"] != user.email:
            new_email = kwargs["email"].lower().strip()
            if new_email in _users and new_email != user.email:
                raise ValueError("Email already exists")
            _users[new_email] = _users.pop(user.email)
            _users[new_email]["email"] = new_email
        if "password" in kwargs:
            _users[user.email]["password_hash"] = _hash_password(kwargs["password"])
        _users[user.email]["updated_at"] = datetime.now(timezone.utc).isoformat()
        return cls(**{**_users.get(user.email, {})})

    @classmethod
    def delete(cls, user_id: str) -> bool:
        user = cls.find_by_id(user_id)
        if not user:
            return False
        del _users[user.email]
        return True

    @classmethod
    def authenticate(cls, email: str, password: str) -> "User | None":
        user = cls.find_by_email(email)
        if not user or not _verify_password(password, user.password_hash):
            return None
        return user

    @classmethod
    def _reset_storage(cls):
        _users.clear()

import functools
import logging
from datetime import datetime, timezone

import jwt
from flask import current_app, g, request, jsonify

from app.models.user import User

logger = logging.getLogger("audit")


class AuthError(Exception):
    status_code = 401

    def __init__(self, message: str, error_type: str = "unauthorized"):
        self.message = message
        self.error_type = error_type


class ForbiddenError(Exception):
    status_code = 403

    def __init__(self, message: str, error_type: str = "forbidden"):
        self.message = message
        self.error_type = error_type


def create_access_token(user_id: str, role: str) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "role": role,
        "type": "access",
        "iat": now,
        "exp": now + current_app.config["JWT_ACCESS_TOKEN_EXPIRES"],
    }
    return jwt.encode(payload, current_app.config["JWT_SECRET"], algorithm="HS256")


def create_refresh_token(user_id: str) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "type": "refresh",
        "iat": now,
        "exp": now + current_app.config["JWT_REFRESH_TOKEN_EXPIRES"],
    }
    return jwt.encode(payload, current_app.config["JWT_SECRET"], algorithm="HS256")


def decode_token(token: str) -> dict:
    try:
        return jwt.decode(token, current_app.config["JWT_SECRET"], algorithms=["HS256"])
    except jwt.ExpiredSignatureError as e:
        raise AuthError("Token has expired", "token_expired") from e
    except jwt.InvalidTokenError as e:
        raise AuthError("Invalid token", "token_invalid") from e


def login_required(f):
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            raise AuthError("Missing or invalid Authorization header", "no_token")

        token = auth_header.split(" ", 1)[1]
        payload = decode_token(token)

        if payload.get("type") != "access":
            raise AuthError("Invalid token type", "invalid_token_type")

        user = User.find_by_id(payload["sub"])
        if not user:
            raise AuthError("User not found", "user_not_found")

        g.current_user = user
        g.token_payload = payload

        logger.info(
            "Authenticated request",
            extra={
                "audit_type": "auth",
                "user_id": user.id,
                "email": user.email,
                "method": request.method,
                "path": request.path,
            },
        )

        return f(*args, **kwargs)

    return decorated


def role_required(*roles: str):
    def decorator(f):
        @functools.wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user.role not in roles:
                raise ForbiddenError(
                    f"Requires one of {roles} role(s)", "insufficient_permissions"
                )
            return f(*args, **kwargs)

        return decorated

    return decorator


def optional_login(f):
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if auth_header.startswith("Bearer "):
            try:
                token = auth_header.split(" ", 1)[1]
                payload = decode_token(token)
                if payload.get("type") == "access":
                    user = User.find_by_id(payload["sub"])
                    if user:
                        g.current_user = user
                        g.token_payload = payload
            except AuthError:
                pass
        return f(*args, **kwargs)

    return decorated

import functools
import threading
import time
from collections import defaultdict

from flask import jsonify, request, current_app


class RateLimiter:
    def __init__(self):
        self._lock = threading.Lock()
        self._windows: dict[str, list[float]] = defaultdict(list)

    def is_rate_limited(self, key: str, limit: int, period: int) -> bool:
        now = time.monotonic()
        with self._lock:
            window = self._windows[key]
            window[:] = [t for t in window if now - t < period]
            if len(window) >= limit:
                return True
            window.append(now)
            return False

    def reset(self):
        with self._lock:
            self._windows.clear()


_rate_limiter = RateLimiter()


def get_rate_limit_key() -> str:
    auth = request.headers.get("Authorization", "")
    if auth.startswith("Bearer "):
        return f"token:{hash(auth) % 100000}"
    return f"ip:{request.remote_addr}"


def rate_limit(limit_str: str | None = None):
    """Decorator that rate limits an endpoint.

    limit_str format: "N per minute" or "N per second"
    """

    def decorator(f):
        @functools.wraps(f)
        def decorated(*args, **kwargs):
            effective_limit = limit_str or current_app.config.get("RATE_LIMIT_DEFAULT", "100 per minute")
            parts = effective_limit.split()
            if len(parts) != 3 or parts[1] != "per":
                return f(*args, **kwargs)

            try:
                n = int(parts[0])
            except ValueError:
                return f(*args, **kwargs)

            unit = parts[2].lower()
            period_map = {"second": 1, "minute": 60, "hour": 3600, "day": 86400}
            period = period_map.get(unit, 60)

            endpoint = request.endpoint or request.path
            key = f"{endpoint}:{get_rate_limit_key()}"

            if _rate_limiter.is_rate_limited(key, limit=n, period=period):
                return jsonify({
                    "error": "rate_limit_exceeded",
                    "message": f"Rate limit exceeded: {limit_str}",
                }), 429

            return f(*args, **kwargs)

        return decorated

    return decorator


def reset_rate_limiter():
    _rate_limiter.reset()

import re

from marshmallow import Schema, fields, validates, validates_schema, ValidationError


class RegisterSchema(Schema):
    email = fields.Email(required=True)
    password = fields.String(required=True, load_only=True)
    name = fields.String(required=True)

    @validates("password")
    def validate_password(self, value):
        if len(value) < 8:
            raise ValidationError("Password must be at least 8 characters")
        if not re.search(r"[A-Z]", value):
            raise ValidationError("Password must contain at least one uppercase letter")
        if not re.search(r"[a-z]", value):
            raise ValidationError("Password must contain at least one lowercase letter")
        if not re.search(r"[0-9]", value):
            raise ValidationError("Password must contain at least one digit")


class LoginSchema(Schema):
    email = fields.Email(required=True)
    password = fields.String(required=True, load_only=True)


class RefreshSchema(Schema):
    refresh_token = fields.String(required=True)


class UserUpdateSchema(Schema):
    email = fields.Email()
    name = fields.String()
    password = fields.String(load_only=True)
    role = fields.String()

    @validates("name")
    def validate_name(self, value):
        if value is not None and len(value.strip()) == 0:
            raise ValidationError("Name must not be empty")

    @validates("password")
    def validate_password(self, value):
        if value is not None and len(value) < 8:
            raise ValidationError("Password must be at least 8 characters")

    @validates("role")
    def validate_role(self, value):
        if value is not None and value not in ("user", "admin"):
            raise ValidationError("Role must be 'user' or 'admin'")


class UserQuerySchema(Schema):
    page = fields.Integer(load_default=1)
    per_page = fields.Integer(load_default=20)

    @validates("page")
    def validate_page(self, value):
        if value < 1:
            raise ValidationError("Page must be >= 1")

    @validates("per_page")
    def validate_per_page(self, value):
        if value < 1 or value > 100:
            raise ValidationError("per_page must be between 1 and 100")


def validate_schema(schema_class: type[Schema]):
    """Decorator that validates request JSON against a Marshmallow schema."""
    def decorator(f):
        def decorated(*args, **kwargs):
            schema = schema_class()
            try:
                data = schema.load(request.get_json(silent=True) or {})
            except ValidationError as e:
                from flask import jsonify
                return jsonify({
                    "error": "validation_error",
                    "message": "Request validation failed",
                    "details": e.messages,
                }), 422
            request.validated_data = data
            return f(*args, **kwargs)
        return decorated
    return decorator


def validate_query_schema(schema_class: type[Schema]):
    """Decorator that validates query parameters against a Marshmallow schema."""
    def decorator(f):
        def decorated(*args, **kwargs):
            schema = schema_class()
            try:
                data = schema.load(request.args.to_dict())
            except ValidationError as e:
                from flask import jsonify
                return jsonify({
                    "error": "validation_error",
                    "message": "Query parameter validation failed",
                    "details": e.messages,
                }), 422
            request.validated_query = data
            return f(*args, **kwargs)
        return decorated
    return decorator

import logging
import sys
import json
from datetime import datetime, timezone

import flask

AUDIT_FIELDS = frozenset({
    "audit_type", "user_id", "email", "method", "path",
    "status_code", "ip", "user_agent", "duration_ms", "request_id",
})


class AuditFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        entry = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname,
            "message": record.getMessage(),
        }
        for field in AUDIT_FIELDS:
            value = getattr(record, field, record.__dict__.get(field))
            if value is not None:
                entry[field] = value
        if record.exc_info and record.exc_info[0]:
            entry["exception"] = self.formatException(record.exc_info)
        extra = getattr(record, "extra", {})
        if isinstance(extra, dict):
            for k, v in extra.items():
                if k not in AUDIT_FIELDS and k not in ("message", "level", "timestamp"):
                    entry[k] = v
        return json.dumps(entry, default=str)


def setup_audit_logging(app: flask.Flask):
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(AuditFormatter())
    handler.setLevel(logging.INFO)

    audit_logger = logging.getLogger("audit")
    audit_logger.handlers.clear()
    audit_logger.addHandler(handler)
    audit_logger.setLevel(logging.INFO)
    audit_logger.propagate = False


def log_request(g: flask.g, response: flask.Response):
    """Log API request details after each request."""
    import logging
    logger = logging.getLogger("audit")
    duration = getattr(g, "request_start_time", None)
    if duration is not None:
        duration = (datetime.now(timezone.utc) - duration).total_seconds() * 1000

    logger.info(
        "API request",
        extra={
            "audit_type": "api_request",
            "method": flask.request.method,
            "path": flask.request.path,
            "status_code": response.status_code if hasattr(response, "status_code") else response.status,
            "ip": flask.request.remote_addr,
            "user_agent": flask.request.headers.get("User-Agent", ""),
            "duration_ms": round(duration, 2) if duration else None,
            "request_id": getattr(g, "request_id", None),
            "user_id": getattr(getattr(g, "current_user", None), "id", None),
        },
    )
    return response

from flask import request


class ValidationError(Exception):
    status_code = 422

    def __init__(self, message: str, details: dict | None = None):
        self.message = message
        self.details = details or {}


class NotFoundError(Exception):
    status_code = 404

    def __init__(self, message: str, error_type: str = "not_found"):
        self.message = message
        self.error_type = error_type


class ConflictError(Exception):
    status_code = 409

    def __init__(self, message: str, error_type: str = "conflict"):
        self.message = message
        self.error_type = error_type


def register_error_handlers(app):
    from app.middleware.auth import AuthError, ForbiddenError

    @app.errorhandler(AuthError)
    def handle_auth_error(error):
        return {
            "error": error.error_type,
            "message": error.message,
        }, error.status_code

    @app.errorhandler(ForbiddenError)
    def handle_forbidden_error(error):
        return {
            "error": error.error_type,
            "message": error.message,
        }, error.status_code

    @app.errorhandler(ValidationError)
    def handle_validation_error(error):
        return {
            "error": "validation_error",
            "message": error.message,
            "details": error.details,
        }, error.status_code

    @app.errorhandler(NotFoundError)
    def handle_not_found_error(error):
        return {
            "error": error.error_type,
            "message": error.message,
        }, error.status_code

    @app.errorhandler(ConflictError)
    def handle_conflict_error(error):
        return {
            "error": error.error_type,
            "message": error.message,
        }, error.status_code

    @app.errorhandler(404)
    def handle_404(error):
        return {
            "error": "not_found",
            "message": "The requested resource was not found",
        }, 404

    @app.errorhandler(405)
    def handle_405(error):
        return {
            "error": "method_not_allowed",
            "message": "The method is not allowed for this endpoint",
        }, 405

    @app.errorhandler(500)
    def handle_500(error):
        return {
            "error": "internal_server_error",
            "message": "An internal server error occurred",
        }, 500

    @app.errorhandler(Exception)
    def handle_unhandled(error):
        import logging
        logger = logging.getLogger("audit")
        logger.error("Unhandled exception", exc_info=error)
        return {
            "error": "internal_server_error",
            "message": "An unexpected error occurred",
        }, 500

from flask import request


def paginate(items: list, total: int, page: int, per_page: int) -> dict:
    total_pages = max(1, (total + per_page - 1) // per_page)

    base_url = request.base_url
    links = {"self": f"{base_url}?page={page}&per_page={per_page}"}

    if page > 1:
        links["first"] = f"{base_url}?page=1&per_page={per_page}"
        links["prev"] = f"{base_url}?page={page - 1}&per_page={per_page}"

    if page < total_pages:
        links["next"] = f"{base_url}?page={page + 1}&per_page={per_page}"
        links["last"] = f"{base_url}?page={total_pages}&per_page={per_page}"

    return {
        "data": items,
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "links": links,
        },
    }

