import logging

from flask import Blueprint, g, jsonify, request, current_app

from app.middleware.auth import (
    create_access_token,
    create_refresh_token,
    decode_token,
    login_required,
)
from app.middleware.rate_limit import rate_limit
from app.middleware.validation import validate_schema
from app.middleware.validation import (
    RegisterSchema,
    LoginSchema,
    RefreshSchema,
)
from app.models.user import User
from app.utils.errors import AuthError, ConflictError

logger = logging.getLogger("audit")
auth_bp = Blueprint("auth_v1", __name__, url_prefix="/api/v1/auth")


@auth_bp.route("/register", methods=["POST"])
@rate_limit(limit_str="10 per minute")
@validate_schema(RegisterSchema)
def register():
    data = request.validated_data
    try:
        user = User.create(
            email=data["email"],
            password=data["password"],
            name=data["name"],
        )
    except ValueError as e:
        raise ConflictError(str(e), "email_exists")

    logger.info(
        "User registered",
        extra={
            "audit_type": "user_register",
            "user_id": user.id,
            "email": user.email,
        },
    )

    access_token = create_access_token(user.id, user.role)
    refresh_token = create_refresh_token(user.id)

    return jsonify({
        "user": user.to_dict(),
        "access_token": access_token,
        "refresh_token": refresh_token,
        "token_type": "Bearer",
    }), 201


@auth_bp.route("/login", methods=["POST"])
@rate_limit(limit_str="5 per minute")
@validate_schema(LoginSchema)
def login():
    data = request.validated_data
    user = User.authenticate(data["email"], data["password"])
    if not user:
        raise AuthError("Invalid email or password", "invalid_credentials")

    access_token = create_access_token(user.id, user.role)
    refresh_token = create_refresh_token(user.id)

    logger.info(
        "User logged in",
        extra={
            "audit_type": "user_login",
            "user_id": user.id,
            "email": user.email,
        },
    )

    return jsonify({
        "user": user.to_dict(),
        "access_token": access_token,
        "refresh_token": refresh_token,
        "token_type": "Bearer",
    })


@auth_bp.route("/refresh", methods=["POST"])
@rate_limit(limit_str="5 per minute")
@validate_schema(RefreshSchema)
def refresh():
    data = request.validated_data
    try:
        payload = decode_token(data["refresh_token"])
    except AuthError as e:
        raise AuthError(str(e), e.error_type)

    if payload.get("type") != "refresh":
        raise AuthError("Invalid token type", "invalid_token_type")

    user = User.find_by_id(payload["sub"])
    if not user:
        raise AuthError("User not found", "user_not_found")

    access_token = create_access_token(user.id, user.role)
    refresh_token = create_refresh_token(user.id)

    return jsonify({
        "access_token": access_token,
        "refresh_token": refresh_token,
        "token_type": "Bearer",
    })


@auth_bp.route("/me", methods=["GET"])
@login_required
def me():
    return jsonify({"user": g.current_user.to_dict()})

import logging

from flask import Blueprint, g, jsonify, request

from app.middleware.auth import login_required, role_required
from app.middleware.rate_limit import rate_limit
from app.middleware.validation import validate_schema, validate_query_schema
from app.middleware.validation import UserUpdateSchema, UserQuerySchema
from app.models.user import User
from app.utils.errors import NotFoundError, ConflictError
from app.utils.pagination import paginate

logger = logging.getLogger("audit")
users_bp = Blueprint("users_v1", __name__, url_prefix="/api/v1/users")


@users_bp.route("", methods=["GET"])
@login_required
@validate_query_schema(UserQuerySchema)
def list_users():
    query = request.validated_query
    page = query["page"]
    per_page = query["per_page"]

    users, total = User.list_all(page=page, per_page=per_page)
    data = [u.to_dict() for u in users]
    result = paginate(data, total, page, per_page)

    return jsonify(result)


@users_bp.route("/<user_id>", methods=["GET"])
@login_required
def get_user(user_id):
    user = User.find_by_id(user_id)
    if not user:
        raise NotFoundError("User not found", "user_not_found")
    return jsonify({"user": user.to_dict()})


@users_bp.route("/<user_id>", methods=["PUT"])
@login_required
@validate_schema(UserUpdateSchema)
def update_user(user_id):
    if g.current_user.role != "admin" and g.current_user.id != user_id:
        from app.middleware.auth import ForbiddenError
        raise ForbiddenError(
            "You can only update your own profile", "insufficient_permissions"
        )

    data = request.validated_data
    if not data:
        raise ConflictError("No fields to update", "no_fields")

    update_data = {k: v for k, v in data.items() if v is not None}

    if "role" in update_data and g.current_user.role != "admin":
        from app.middleware.auth import ForbiddenError
        raise ForbiddenError(
            "Only admins can change roles", "insufficient_permissions"
        )

    try:
        user = User.update(user_id, **update_data)
    except ValueError as e:
        raise ConflictError(str(e), "email_exists")

    if not user:
        raise NotFoundError("User not found", "user_not_found")

    logger.info(
        "User updated",
        extra={
            "audit_type": "user_update",
            "user_id": user.id,
            "email": user.email,
            "actor_id": g.current_user.id,
        },
    )

    return jsonify({"user": user.to_dict()})


@users_bp.route("/<user_id>", methods=["DELETE"])
@login_required
@role_required("admin")
def delete_user(user_id):
    if g.current_user.id == user_id:
        raise ConflictError(
            "Cannot delete your own account", "cannot_delete_self"
        )

    deleted = User.delete(user_id)
    if not deleted:
        raise NotFoundError("User not found", "user_not_found")

    logger.info(
        "User deleted",
        extra={
            "audit_type": "user_delete",
            "user_id": user_id,
            "actor_id": g.current_user.id,
        },
    )

    return jsonify({"message": "User deleted successfully"})
